class AuditStore:
    """Append-only in-memory store for migrated audit events."""

    __slots__ = ("_events", "_evt_ids")

    def __init__(self) -> None:
        self._events: list[dict] = []
        self._evt_ids: set[int] = set()

    def append(self, event: dict) -> None:
        stored_event = event.copy()
        self._events.append(stored_event)
        self._evt_ids.add(stored_event["evt_id"])

    def events(self) -> list[dict]:
        return [event.copy() for event in self._events]

    def __len__(self) -> int:
        return len(self._events)

    def _contains_evt_id(self, evt_id: int) -> bool:
        return evt_id in self._evt_ids


def migrate_event(row: dict) -> dict:
    timestamp = row["EVT_TS"]
    return {
        "evt_id": int(row["EVT_ID"]),
        "ts": (
            f"{timestamp[0:4]}-{timestamp[4:6]}-{timestamp[6:8]}"
            f"T{timestamp[8:10]}:{timestamp[10:12]}:{timestamp[12:14]}"
        ),
        "code": row["EVT_CD"],
        "user_id": row["USR_ID"],
        "entity": row["ENT_NAME"],
        "entity_id": row["ENT_ID"],
        "old_val": row["OLD_VAL"],
        "new_val": row["NEW_VAL"],
    }


def migrate(
    rows: list[dict],
    store: AuditStore | None = None,
) -> AuditStore:
    if store is None:
        store = AuditStore()

    for row in sorted(rows, key=lambda item: int(item["EVT_ID"])):
        evt_id = int(row["EVT_ID"])
        if not store._contains_evt_id(evt_id):
            store.append(migrate_event(row))

    return store
